export const maria = mockData.sampleEntrepreneurs[0];
export const nationalSummary = mockData.nationalSummary;
export const demographicSegments = mockData.demographicSegments;
export const departments = mockData.dimensions.departments;
export const sectors = mockData.dimensions.sectors;
export const sexes = mockData.dimensions.sexes;
export const ageGroups = mockData.dimensions.ageGroups;
export const departmentSummary = mockData.departmentSummary;
export const trainings = mockData.trainings;
export const opportunities = mockData.opportunities;
export const performanceMetrics = mockData.performance.definitions;

export type DashboardFilters = {
  department?: string;
  sector?: string;
  sex?: string;
  ageGroup?: string;
};

/** Shared predicate for summary and performance data, including extended cohorts. */
export function matchesDashboardFilters(row: { department: string; sector: string; sex: string; ageGroup: string }, filters: DashboardFilters = {}) {
  return (Object.keys(filters) as (keyof DashboardFilters)[]).every((key) =>
    !filters[key] || filters[key] === "Todos" || row[key] === filters[key]
  );
}

/** Aggregate dashboard values from the 810 internally-consistent demographic segments. */
export function getDashboardMetrics(filters: DashboardFilters = {}) {
  const rows = demographicSegments.filter((row) => matchesDashboardFilters(row, filters));

  const sum = (key: "registered" | "active" | "revenueBs" | "capitalMobilizedBs" | "creditsGranted" | "protected" | "marketIntegrated" | "benefitsDeliveredBs") =>
    rows.reduce((acc, row) => acc + row[key], 0);

  const registered = sum("registered");
  const active = sum("active");

  return {
    registered,
    active,
    revenueBs: sum("revenueBs"),
    capitalMobilizedBs: sum("capitalMobilizedBs"),
    creditsGranted: sum("creditsGranted"),
    protected: sum("protected"),
    marketIntegrated: sum("marketIntegrated"),
    benefitsDeliveredBs: sum("benefitsDeliveredBs"),
    activationRatePct: registered ? Number(((active / registered) * 100).toFixed(1)) : 0,
    creditAccessPct: active ? Number(((sum("creditsGranted") / active) * 100).toFixed(1)) : 0,
    protectionPct: active ? Number(((sum("protected") / active) * 100).toFixed(1)) : 0,
    marketAccessPct: active ? Number(((sum("marketIntegrated") / active) * 100).toFixed(1)) : 0,
  };
}
